function say(t) {
  const speech = $('speech');
  if (speech) speech.textContent = t;
}

function alertToast(t) {
  const toast = $('toast');
  if (!toast) return;
  toast.textContent = t;
  toast.classList.remove('hide');
  clearTimeout(window.toastT);
  window.toastT = setTimeout(() => toast.classList.add('hide'), 2400);
}

function setBg(n) {
  const game = $('game');
  if (game && BG[n]) game.style.backgroundImage = `url("${BG[n]}")`;
}

function tone(hz = 540, d = .1) {
  if (muted) return;
  try {
    const c = new (window.AudioContext || window.webkitAudioContext)();
    const o = c.createOscillator();
    const g = c.createGain();
    o.frequency.value = hz;
    g.gain.value = .04;
    o.connect(g);
    g.connect(c.destination);
    o.start();
    o.stop(c.currentTime + d);
    o.onended = () => c.close();
  } catch (_) {}
}

function safeSave() {
  try {
    localStorage.setItem('sheep-v6-settings', JSON.stringify(settings));
    localStorage.setItem('sheep-awards', JSON.stringify([...cleared]));
  } catch (_) {}
}

// 讀取本地儲存與過關進度
try {
  let s = JSON.parse(localStorage.getItem('sheep-v6-settings') || 'null');
  if (s) {
    for (const k of Object.keys(DEFAULTS)) {
      if (s[k] !== undefined) settings[k] = s[k];
    }
  }
  cleared = new Set(JSON.parse(localStorage.getItem('sheep-awards') || '[]'));
} catch (_) {}

// 讀取 URL 覆寫參數
if (urlParams.has('mode')) settings.timeMode = urlParams.get('mode') === 'stage' ? 'stage' : 'total';
if (urlParams.has('total')) settings.totalMinutes = clamp(Number(urlParams.get('total')) || 10, 1, 120);
if (urlParams.has('notime')) settings.noTime = urlParams.get('notime') === '1';
if (urlParams.has('times')) {
  const x = urlParams.get('times').split(',').map(Number);
  if (x.length === 3 && x.every(v => Number.isFinite(v) && v >= 1 && v <= 60)) {
    settings.minutes = [0, ...x];
  }
}

if (studentMode) {
  document.body.classList.add('is-student-mode');
  teacherMode = false;
}

function clamp(v, a, b) {
  return Math.max(a, Math.min(b, Math.round(v)));
}

function modal(html) {
  pauseClock();
  const overlay = $('overlay');
  if (!overlay) return;
  overlay.innerHTML = `<div class="modal">${html}</div>`;
  overlay.classList.remove('hide');
}

function closeModal() {
  const overlay = $('overlay');
  if (overlay && !overlay.classList.contains('hide')) {
    overlay.classList.add('hide');
    overlay.innerHTML = '';
    resumeClock();
  }
}

function pauseClock() {
  if (stage && !ended && !clockPauseAt) clockPauseAt = Date.now();
}

function resumeClock() {
  if (clockPauseAt) {
    let elapsed = Date.now() - clockPauseAt;
    stageEndAt += elapsed;
    if (settings.timeMode === 'total' && sessionEndAt) sessionEndAt += elapsed;
    if (challengeEndAt) challengeEndAt += elapsed;
    clockPauseAt = 0;
  }
}

function remainingMs() {
  if (settings.noTime) return 999999;
  if (!stage) return 0;
  return Math.max(0, (settings.timeMode === 'total' ? sessionEndAt : stageEndAt) - (clockPauseAt || Date.now()));
}

function mmss(ms) {
  if (settings.noTime) return '∞ 無限時';
  let s = Math.ceil(ms / 1000);
  return String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');
}

