function onTimeModeChange(val) {
  settings.timeMode = val;
  const stageRow = $('stageTimesRow');
  const totalLbl = $('totalMinutesLabel');
  if (stageRow) stageRow.classList.toggle('hidden', val !== 'stage');
  if (totalLbl) totalLbl.style.display = val === 'total' ? 'flex' : 'none';
  safeSave();
}

function onNoTimeChange(checked) {
  settings.noTime = checked;
  safeSave();
  head();
}

// 產生學生端專屬網址
function generateStudentUrl() {
  const base = window.location.origin + window.location.pathname;
  const p = new URLSearchParams();
  p.set('student', '1');
  p.set('v', '1.0');

  if (activeQuestionUnit && activeQuestionUnit !== 'demo') {
    p.set('unit', activeQuestionUnit);
  }

  const tm = $('timeModeSelect')?.value || settings.timeMode;
  p.set('mode', tm);

  if ($('noTimeCheck')?.checked) {
    p.set('notime', '1');
  } else if (tm === 'total') {
    const mins = Number($('totalMinutesInput')?.value) || settings.totalMinutes;
    p.set('total', String(mins));
  } else {
    const t1 = Number($('timeStage1')?.value) || settings.minutes[1];
    const t2 = Number($('timeStage2')?.value) || settings.minutes[2];
    const t3 = Number($('timeStage3')?.value) || settings.minutes[3];
    p.set('times', `${t1},${t2},${t3}`);
  }

  return `${base}?${p.toString()}`;
}

function renderStudentQRCode() {
  const url = generateStudentUrl();
  const input = $('studentUrlInput');
  const qrDiv = $('studentQRCode');
  const link = $('testStudentLaunchLink');
  const qrArea = $('studentQRArea');

  if (input) input.value = url;
  if (link) link.href = url;
  if (qrDiv) {
    qrDiv.replaceChildren();
    if (window.QRCode) {
      new window.QRCode(qrDiv, {
        text: url,
        width: 170,
        height: 170,
        colorDark: '#4a2f13',
        colorLight: '#ffffff',
        correctLevel: window.QRCode.CorrectLevel.M
      });
    }
  }
  if (qrArea) qrArea.classList.remove('hidden');
}

function launchStudentView() {
  const url = generateStudentUrl();
  const win = window.open(url, '_blank', 'noopener,noreferrer');
  if (!win || win.closed || typeof win.closed === 'undefined') {
    if (confirm('瀏覽器攔截了自動開啟新分頁！是否直接在當前視窗載入學生版？')) {
      window.location.href = url;
    }
  }
}

async function copyStudentUrl() {
  const input = $('studentUrlInput');
  const feedback = $('copyUrlFeedback');
  if (!input) return;
  try {
    await navigator.clipboard.writeText(input.value);
    if (feedback) {
      feedback.textContent = '✅ 已成功複製學生端連結！可直接傳送給全班。';
      setTimeout(() => feedback.textContent = '', 3500);
    }
  } catch (_) {
    alertToast('請手動選取並複製網址：' + input.value);
  }
}

// 📚 連線全平台 manifest.json 題庫
async function loadManifestAndPopulateSelect() {
  const select = $('unitSelect');
  if (!select) return;

  try {
    const candidates = ['../questions/manifest.json', 'questions/manifest.json'];
    let res = null;
    for (const u of candidates) {
      try {
        const r = await fetch(u);
        if (r.ok) { res = r; break; }
      } catch (_) {}
    }
    if (!res) throw new Error('無法連線題庫清單');

    const manifest = await res.json();
    select.innerHTML = '<option value="demo">✨ 羊羊農場原生生物題庫 (24 題 108 課綱核心試題)</option>';

    if (Array.isArray(manifest.publishers)) {
      manifest.publishers.forEach(pub => {
        if (pub.status === 'placeholder' || !Array.isArray(pub.semesters)) return;
        pub.semesters.forEach(sem => {
          if (!Array.isArray(sem.units) || sem.units.length === 0) return;
          const grp = document.createElement('optgroup');
          grp.label = `📘 ${pub.name} - ${sem.name}`;
          sem.units.forEach(un => {
            const opt = document.createElement('option');
            opt.value = un.file;
            opt.textContent = `${un.title} (${un.count} 題)`;
            grp.appendChild(opt);
          });
          select.appendChild(grp);
        });
      });
    }

    const targetUnit = urlParams.get('unit');
    if (targetUnit) {
      select.value = targetUnit;
      await onSelectUnitChange(targetUnit);
    } else {
      const loadInfo = $('loadInfo');
      if (loadInfo) loadInfo.textContent = '✅ 已成功連線全平台題庫；當前採用「羊羊農場原生生物題庫 (24 題)」。';
    }
  } catch (err) {
    const loadInfo = $('loadInfo');
    if (loadInfo) loadInfo.textContent = '展示模式：使用內建 24 題 108 課綱核心生物試題。';
  }
}

async function onSelectUnitChange(unitPath) {
  activeQuestionUnit = unitPath;
  const badge = $('unitLoadedBadge');
  const info = $('loadInfo');

  if (unitPath === 'demo' || !unitPath) {
    questionBank = EXAMPLE_BANK.map(x => ({ ...x }));
    if (badge) badge.textContent = '✅ 當前題庫：羊羊農場原生生物題庫 (24 題)';
    if (info) info.textContent = '使用內建 24 題 108 課綱核心生物試題。';
    return;
  }

  try {
    if (info) info.textContent = '正在載入題庫單元：' + unitPath + '……';
    const urls = ['../questions/' + unitPath, 'questions/' + unitPath];
    let res = null;
    for (const u of urls) {
      try {
        const r = await fetch(u);
        if (r.ok) { res = r; break; }
      } catch (_) {}
    }
    if (!res) throw new Error('找不到題庫檔案');

    const data = await res.json();
    const rawList = data.questions || (Array.isArray(data) ? data : []);
    if (!rawList.length) throw new Error('該單元無可用試題');

    questionBank = rawList.map((q, i) => {
      let ans = q.answer;
      if (typeof ans === 'string') {
        const letters = ['A', 'B', 'C', 'D'];
        const idx = letters.indexOf(ans.trim().toUpperCase());
        if (idx >= 0) ans = idx;
        else ans = q.options.findIndex(o => o && o.trim() === q.answer.trim());
      }
      if (ans === -1 || ans === undefined || ans === null) ans = 0;
      return {
        id: String(q.id || 'QB-' + (i + 1)),
        unit: String(q.unit || '自然領域'),
        difficulty: Number(q.difficulty) || 2,
        question: String(q.question || ''),
        options: Array.isArray(q.options) ? q.options.map(String) : ['A', 'B', 'C', 'D'],
        answer: ans,
        explanation: String(q.explanation || '依據國中生物學科原理可知正確解答。')
      };
    });

    const select = $('unitSelect');
    const selectedText = select?.options[select.selectedIndex]?.text || unitPath;
    if (badge) badge.textContent = '✅ 已套用題庫：' + selectedText;
    if (info) info.textContent = `成功載入單元「${selectedText}」，共 ${questionBank.length} 題已連線！`;
    alertToast('題庫已切換為：' + selectedText);
  } catch (err) {
    if (badge) badge.textContent = '⚠️ 載入失敗，維持內建題庫';
    if (info) info.textContent = '連線失敗，自動回退為羊羊農場原生 24 題。';
    questionBank = EXAMPLE_BANK.map(x => ({ ...x }));
  }
}

function showRules() {
  modal(`
    <h2>📖 羊羊分類消除玩法</h2>
    <p>🐥 <strong>1. 看清小雞任務：</strong>依上方任務標題，在 6×4 盤面找出三張符合條件的相同圖卡。</p>
    <p>🧺 <strong>2. 暫存槽機制（7 格）：</strong>點選的圖卡會進入下方暫存槽；集滿 3 張相同且符合任務即成功消除！若選到不符合條件的圖卡會自動退回原位，不扣罰。</p>
    <p>📖 <strong>3. 共同題庫闖關：</strong>消除過程中會穿插生物選擇題挑戰，答對才能繼續解救小羊。答題期間時間完全暫停！</p>
    <p>🐺 <strong>4. 第三關野狼追擊：</strong>第三關部分任務會啟動限時選牌，時間到野狼會追上來，但不會清除已選牌卡，隨時可再次挑戰！</p>
    <button type="button" class="btn" onclick="closeModal()">我懂了，開始挑戰！</button>
  `);
}

function currentTask() {
  return stageTasks[taskIndex] || null;
}

function visibleTriples() {
  const groups = new Map();
  board.forEach(p => {
    if (!p.length) return;
    let c = p[p.length - 1];
    if (!groups.has(c.groupIndex)) groups.set(c.groupIndex, { card: c, count: 0 });
    groups.get(c.groupIndex).count++;
  });
  return [...groups.values()].filter(x => x.count === 3).map(x => x.card);
}

function chooseNextCategory() {
  const candidates = visibleTriples().filter(c => !c.decoy);
  if (!candidates.length) return;
  let last = taskIndex > 0 ? stageTasks[taskIndex - 1]?.key : null;
  let different = candidates.filter(c => c.key !== last);
  let pool = different.length ? different : candidates;
  stageTasks[taskIndex] = { key: pool[Math.floor(random() * pool.length)].key, groups: 1 };
}

function makeTaskBoard(n) {
  const keys = TASK_KEYS[n];
  const groups = n === 1 ? 6 : n === 2 ? 8 : 10;
  const lanes = 8;
  taskIndex = 0;
  taskGroupsDone = 0;
  groupPlan = [];

  const categories = n === 3
    ? shuffle(['plant', 'plant', 'vegetative', 'vegetative', 'reproductive', 'reproductive', 'reproductive', 'gymnosperm', 'animal', 'fungi'])
    : shuffle(Array.from({ length: groups }, (_, i) => keys[i % keys.length]));

  const iconUsed = {};
  const stage3Deck = n === 3
    ? Object.fromEntries(Object.entries(STAGE3_POOL).map(([key, cards]) => [key, shuffle(cards.slice())]))
    : {};

  if (n === 3) stage3Deck.reproductive = shuffle(STAGE3_POOL.reproductive.slice());

  for (let i = 0; i < groups; i++) {
    const key = categories[i];
    const cards = n === 3 ? stage3Deck[key] : BIO[key].cards;
    const card = cards[(iconUsed[key] || 0) % cards.length];
    iconUsed[key] = (iconUsed[key] || 0) + 1;
    groupPlan.push({ key, emoji: card[0], name: card[1], categoryLabel: n === 3 ? card[2] : '', groupIndex: i });
  }

  board = Array.from({ length: lanes * 3 }, () => []);
  const laneOrder = shuffle(Array.from({ length: lanes }, (_, i) => i));

  // 第一關加入兩組干擾項（真菌香菇與完整蘋果樹）
  const decoys = n === 1 ? [
    { key: 'fungi', emoji: '🍄', name: '香菇（真菌無器官）', groupIndex: -1, decoy: true },
    { key: 'plant', emoji: '🌳', name: '蘋果樹（整株個體）', groupIndex: -2, decoy: true, fruitTree: true }
  ] : [];

  const arranged = shuffle([...groupPlan, ...decoys]);
  arranged.forEach((card, i) => {
    const lane = laneOrder[i % lanes];
    for (let j = 0; j < 3; j++) board[lane * 3 + j].push(card);
  });

  stageTasks = Array.from({ length: groups }, () => ({ key: null, groups: 1 }));
  chooseNextCategory();

  challengeTasks = new Set();
  challengeFailed = new Set();
  if (n === 3) {
    const eligible = shuffle(Array.from({ length: groups }, (_, i) => i));
    for (let i = 0; i < Math.min(settings.challengeCount, groups); i++) challengeTasks.add(eligible[i]);
  }
}

function taskBanner() {
  let t = currentTask();
  if (!t) return '<div class="bioTask"><strong>🎉 分類任務全部完成！</strong></div>';
  let timed = stage === 3 && challengeTasks.has(taskIndex);
  return `
    <div class="bioTask">
      <div class="bioTaskTag">🐥 分類任務 ${taskIndex + 1}／${stageTasks.length} ${timed ? '｜🐺 野狼追擊！' : ''}</div>
      <strong>找出三張相同的「<em>${BIO[t.key].label}</em>」圖卡！</strong>
      <small>本任務 ${taskGroupsDone}／${t.groups} 組${timed ? '｜⏱ 限時選牌 <b id="challengeClock">' + settings.challengeSeconds + '</b> 秒' : ''}</small>
    </div>
  `;
}

function pickQuizPool(n) {
  const want = settings.questionCounts[n];
  if (want <= 0) return [];
  const unit = settings.unit;
  let available = questionBank.filter(q => (unit === '全部' || q.unit === unit) && !askedIds.has(q.id));

  if (!available.length) {
    available = EXAMPLE_BANK.filter(q => !askedIds.has(q.id));
  }

  let exact = shuffle(available.filter(q => q.difficulty === n));
  let fallback = shuffle(available.filter(q => q.difficulty !== n).sort((a, b) => Math.abs(a.difficulty - n) - Math.abs(b.difficulty - n)));
  let pool = [...exact, ...fallback];
  return pool.slice(0, want);
}

function makeMilestones(n) {
  const q = questionQueue.length, g = LEVELS[n].groups;
  return Array.from({ length: q }, (_, i) => Math.max(1, Math.min(g, Math.floor((i * g) / Math.max(1, q)) + 1)));
}

async function startLevel(n) {
  closeModal();
  stage = n;
  ended = false;
  wrongBusy = false;
  tray = [];
  history = [];
  usedUndo = 0;
  rescueAsked = 0;
  matched = 0;
  questionsAnswered = 0;
  quizOpen = false;
  quizLock = false;
  activeQuestion = null;
  seed = (Date.now() ^ n * 591482) >>> 0;

  makeTaskBoard(n);
  questionQueue = pickQuizPool(n);
  questionMilestones = makeMilestones(n);

  stageEndAt = Date.now() + settings.minutes[n] * 60000;
  if (settings.timeMode === 'total' && !sessionStarted) {
    sessionEndAt = Date.now() + settings.totalMinutes * 60000;
    sessionStarted = true;
  }
  clockPauseAt = 0;
  challengeEndAt = 0;
  askedIds = new Set(askedIds);

  setBg(n);
  $('home').classList.add('hide');
  $('main').classList.remove('hide');

  // 若為教師端巡堂，進入關卡時自動收合左側面板
  if (!studentMode) {
    collapseTeacherHome();
  }

  say(['', '先找出植物的營養器官或生殖器官！', '認出動物界、植物界和真菌界！', '野狼來了！快看清分類任務！'][n]);
  head();
  render();

  modal(`
    <h2>第 ${n} 關｜${LEVELS[n].title}</h2>
    <p>${LEVELS[n].intro}</p>
    <p>⏱ ${settings.noTime ? '無時間壓力模式' : (settings.timeMode === 'total' ? '全場 ' + settings.totalMinutes + ' 分鐘（剩餘 ' + mmss(remainingMs()) + '）' : '本關 ' + settings.minutes[n] + ' 分鐘')}｜📖 ${questionQueue.length} 道生物挑戰題｜🧩 ${stageTasks.length} 個分類任務</p>
    <p>${n === 3 ? '🐺 其中 ' + challengeTasks.size + ' 個分類任務需要在 ' + settings.challengeSeconds + ' 秒內選牌。' : '選出三張相同且符合條件的圖卡進行消除。'}</p>
    <button type="button" class="btn" onclick="closeModal();startChallengeIfNeeded();maybeAskQuiz()">🐑 開始挑戰</button>
  `);
}

function startChallengeIfNeeded() {
  challengeEndAt = stage === 3 && challengeTasks.has(taskIndex) ? Date.now() + settings.challengeSeconds * 1000 : 0;
}

function render() {
  if (!stage) return;
  let remaining = board.reduce((n, p) => n + p.filter(c => !c.decoy).length, 0);

  const status = $('status');
  if (status) {
    status.innerHTML = `
      <span>🌾 第 ${stage} 關｜${LEVELS[stage].title}</span>
      <span>目標圖卡剩餘 <b>${remaining}</b> 張｜已消除 <b>${matched}</b> 張</span>
      <span class="quizProgress">📖 題庫 ${questionsAnswered}/${questionQueue.length}｜🧠 分類 ${taskIndex}/${stageTasks.length}</span>
    `;
  }

  const boardEl = $('board');
  if (boardEl) {
    boardEl.style.gridTemplateRows = `repeat(${Math.ceil(board.length / 6)}, minmax(0, 1fr))`;
    boardEl.innerHTML = board.map((pile, i) => `
      <div class="tilecell">
        ${pile.length > 1 ? '<div class="back"></div>' : ''}
        ${pile.length > 2 ? '<div class="back b2"></div>' : ''}
        ${pile.length ? `
          <button type="button" class="tile" aria-label="${esc(pile[pile.length - 1].name)}" onclick="pick(${i})">
            ${stage === 3 && pile[pile.length - 1].categoryLabel ? `<span class="tileCategory">${esc(pile[pile.length - 1].categoryLabel)}</span>` : ''}
            <span class="emo${pile[pile.length - 1].fruitTree ? ' fruitTree' : ''}">${tileArt(pile[pile.length - 1])}</span>
            <span class="tileName">${esc(pile[pile.length - 1].name)}</span>
            ${pile.length > 1 ? `<span class="depth">×${pile.length}</span>` : ''}
          </button>
        ` : ''}
      </div>
    `).join('');
  }

  const trayEl = $('tray');
  if (trayEl) {
    trayEl.innerHTML = Array.from({ length: 7 }, (_, i) => `
      <div class="slot">${tray[i] ? tileArt(tray[i]) : ''}</div>
    `).join('');
  }

  const taskHeadline = $('taskHeadline');
  if (taskHeadline) taskHeadline.innerHTML = taskBanner();

  const side = $('side');
  if (side) {
    side.innerHTML = `
      <h2>🧰 羊羊救援工具</h2>
      <div class="tools">
        <button type="button" class="btn" onclick="undo()">↩ 撤回 (${1 - usedUndo})</button>
        <button type="button" class="btn alt" onclick="rescue()">🧺 退回 (${Math.max(0, settings.rescueLimits[stage] - rescueAsked)})</button>
      </div>
      <p>💡 看清楚上方分類條件，再找三張相同圖卡。不符合任務的圖卡會退回原位，不會鎖住。</p>
      <button type="button" class="btn dark small" onclick="startLevel(stage)">🔄 重新挑戰本關</button>
      <div class="foot">分類挑戰與題庫交錯出現；四選一題目來自共同題庫。題目答錯可重試，不增加題數。</div>
    `;
  }

  updateClocks();
}

function snapshot() {
  history.push({
    board: board.map(p => p.slice()),
    tray: tray.slice(),
    taskIndex,
    taskGroupsDone,
    matched,
    challengeEndAt,
    stageTasks: stageTasks.map(x => ({ ...x }))
  });
  if (history.length > 30) history.shift();
}

function advanceTask() {
  taskIndex++;
  taskGroupsDone = 0;
  challengeEndAt = 0;
  if (taskIndex < stageTasks.length) {
    chooseNextCategory();
    say('太棒了！分類成功！');
    alertToast('新任務：' + BIO[currentTask().key].label);
  } else {
    say('太棒了！所有目標都完成了！其他干擾圖卡不用清除。');
  }
}

function matchesCategory(card, taskKey) {
  if (!card || card.decoy) return false;
  if (stage === 3 && taskKey === 'vegetative' && ['FERN7', 'PINE7', 'BROAD7'].includes(card.emoji)) return true;
  if (taskKey === 'plant') return card.key === 'plant' || (stage === 3 && ['vegetative', 'reproductive'].includes(card.key));
  return card.key === taskKey;
}

function tileArt(card) {
  const art = {
    FERN: `<svg class="bioIcon" viewBox="0 0 100 100" role="img" aria-label="蕨類" xmlns="http://www.w3.org/2000/svg"><path d="M49 91Q52 48 57 13" fill="none" stroke="#36693c" stroke-width="5" stroke-linecap="round"/><g fill="#39a660" stroke="#25834a" stroke-width="1.5"><path d="M54 22Q35 7 23 16Q28 29 52 32Z"/><path d="M55 28Q75 7 88 20Q81 35 54 38Z"/><path d="M52 40Q28 25 12 38Q21 52 51 52Z"/><path d="M54 46Q75 29 91 42Q84 56 53 58Z"/><path d="M50 59Q30 48 17 63Q27 75 49 70Z"/><path d="M52 64Q69 52 84 65Q75 78 51 75Z"/></g><path d="M49 91Q44 83 35 82M50 91Q57 83 68 82" fill="none" stroke="#4a7d40" stroke-width="4"/></svg>`,
    MOSS: `<svg class="bioIcon" viewBox="0 0 100 100" role="img" aria-label="苔蘚" xmlns="http://www.w3.org/2000/svg"><path d="M10 82Q50 93 90 82L87 91H13Z" fill="#765c42"/><g stroke="#428c3c" stroke-width="3" stroke-linecap="round"><path d="M23 83V46M39 85V37M54 85V42M70 83V34M81 84V50"/></g><g fill="#6abd55"><ellipse cx="19" cy="50" rx="9" ry="13" transform="rotate(-35 19 50)"/><ellipse cx="28" cy="43" rx="9" ry="13" transform="rotate(35 28 43)"/><ellipse cx="34" cy="38" rx="9" ry="14" transform="rotate(-30 34 38)"/><ellipse cx="44" cy="32" rx="9" ry="14" transform="rotate(35 44 32)"/><ellipse cx="50" cy="49" rx="9" ry="15" transform="rotate(-30 50 49)"/><ellipse cx="60" cy="43" rx="9" ry="14" transform="rotate(30 60 43)"/><ellipse cx="67" cy="36" rx="9" ry="14" transform="rotate(-30 67 36)"/><ellipse cx="78" cy="43" rx="9" ry="15" transform="rotate(30 78 43)"/></g></svg>`,
    PINE: `<svg class="bioIcon" viewBox="0 0 100 100" role="img" aria-label="松樹與毬果" xmlns="http://www.w3.org/2000/svg"><path d="M46 77h11v19H46z" fill="#885b39"/><path d="M51 9 15 59h16L10 76h82L71 59h16Z" fill="#32875a" stroke="#266c49" stroke-width="2"/><path d="M50 22 31 56M50 22 71 56" stroke="#7dbd7b" stroke-width="3" opacity=".7"/><ellipse cx="67" cy="65" rx="8" ry="13" fill="#93592f"/><path d="M62 59h11M61 66h13M63 73h9" stroke="#e4b577" stroke-width="2"/></svg>`,
    FRUIT_TREE: `<svg class="bioIcon" viewBox="0 0 100 100" role="img" aria-label="結果的蘋果樹" xmlns="http://www.w3.org/2000/svg"><path d="M46 65h11v30H46Z" fill="#94603b"/><path d="M21 60C5 51 13 29 30 28 25 11 47 8 53 22 68 7 88 24 79 39 99 44 90 69 74 69H29Z" fill="#69ad54" stroke="#448542" stroke-width="3"/><g fill="#ed3e43" stroke="#a72f36" stroke-width="1"><circle cx="32" cy="44" r="7"/><circle cx="62" cy="37" r="7"/><circle cx="71" cy="57" r="7"/></g><path d="M32 35q3-7 7-4M62 28q3-7 7-4M71 48q3-7 7-4" fill="none" stroke="#347b32" stroke-width="3"/></svg>`,
    REISHI: `<svg class="bioIcon" viewBox="0 0 100 100" role="img" aria-label="靈芝" xmlns="http://www.w3.org/2000/svg"><path d="M48 57 42 93h19L57 53Z" fill="#d5b18c" stroke="#a47b5e" stroke-width="3"/><path d="M9 60Q16 20 53 21 85 21 92 59 84 74 47 72 17 77 9 60Z" fill="#904729" stroke="#593522" stroke-width="4"/><path d="M17 59Q31 33 53 31 74 31 84 57 69 66 50 63 28 69 17 59Z" fill="#c87b43"/><path d="M23 57Q39 40 57 40 72 40 78 54" fill="none" stroke="#f1c38b" stroke-width="5" stroke-linecap="round"/><path d="M30 59Q52 47 67 57" fill="none" stroke="#8c4326" stroke-width="4"/></svg>`,
    BAMBOO_FUNGUS: `<svg class="bioIcon" viewBox="0 0 100 100" role="img" aria-label="竹笙" xmlns="http://www.w3.org/2000/svg"><path d="M33 35Q50 9 67 35L65 45H35Z" fill="#675443" stroke="#4f4236" stroke-width="3"/><path d="M44 41H58V91H44Z" fill="#f8f0dc" stroke="#bcae92" stroke-width="2"/><path d="M35 46Q16 61 24 91H78Q86 61 66 46Z" fill="#f4e7cb" stroke="#c5b79b" stroke-width="2"/><g fill="none" stroke="#baa98b" stroke-width="2"><path d="M32 55 66 88M26 70 49 91M49 52 76 77M69 55 34 88M58 51 25 81M78 70 57 91"/></g></svg>`
  };
  if (stage === 3 && STAGE3_ART[card.emoji]) return `<img class="stage3Art" alt="" src="${STAGE3_ART[card.emoji]}">`;
  return art[card.emoji] || card.emoji;
}

function pick(i) {
  if (!stage || ended || wrongBusy || quizOpen || !$('overlay').classList.contains('hide') || !board[i]?.length) return;
  if (maybeAskQuiz()) return;

  const icon = board[i][board[i].length - 1];
  const t = currentTask();
  if (!t) return;

  if (challengeEndAt && Date.now() >= challengeEndAt) {
    timeChallengeFailed();
    return;
  }

  // 檢查是否符合當前小雞指派的分類任務
  if (!matchesCategory(icon, t.key)) {
    wrongBusy = true;
    board[i].pop();
    tray.push({ ...icon, sourceIndex: i });
    render();
    say('再想想：這張圖卡符合「' + BIO[t.key].label + '」嗎？');
    tone(280);
    setTimeout(() => {
      if (!stage || ended) return;
      const k = tray.findIndex(x => x.groupIndex === icon.groupIndex && x.sourceIndex === i);
      if (k >= 0) tray.splice(k, 1);
      board[i].push(icon);
      wrongBusy = false;
      render();
    }, 650);
    return;
  }

  if (tray.length && tray.some(x => x.groupIndex !== icon.groupIndex)) {
    say('分類正確！但請先找齊暫存槽裡同一張圖卡的另外兩張。');
    alertToast('先完成目前這組三張相同圖卡');
    return;
  }

  snapshot();
  board[i].pop();
  tray.push({ ...icon, sourceIndex: i });
  tone(500);

  const count = tray.filter(x => x.groupIndex === icon.groupIndex).length;
  if (count >= 3) {
    let removed = 0;
    tray = tray.filter(x => {
      if (x.groupIndex === icon.groupIndex && removed < 3) {
        removed++;
        return false;
      }
      return true;
    });
    matched += 3;
    advanceTask();
    tone(890, .17);
  } else {
    say('正確！還差 ' + (3 - count) + ' 張相同圖卡！');
  }

  render();

  if (count >= 3) {
    startChallengeIfNeeded();
    if (maybeAskQuiz()) return;
    checkCompletion();
  }

  if (tray.length >= 7) {
    modal(`
      <h2>😵 暫存槽滿了！</h2>
      <p>可以使用免費救援退回圖卡，或重新挑戰本關。</p>
      <button type="button" class="btn alt" onclick="closeModal();rescue()">🧺 免費救援退回</button>
      <button type="button" class="btn" onclick="startLevel(stage)">🔄 重玩本關</button>
    `);
  }
}

function maybeAskQuiz() {
  if (!stage || ended || quizOpen || questionsAnswered >= questionQueue.length) return false;
  const target = questionMilestones[questionsAnswered] ?? 1;
  if (taskIndex >= target || matched / 3 >= target) {
    showQuiz();
    return quizOpen;
  }
  return false;
}

function teacherTestQuiz() {
  if (!stage) {
    alertToast('請先進入第一、二或第三關，再測試題庫出題');
    return;
  }
  if (quizOpen) {
    alertToast('目前已有試題正在作答中');
    return;
  }
  if (!questionQueue.length) {
    alertToast('本關目前題庫是 0 題，請檢查題庫設定');
    return;
  }
  if (questionsAnswered >= questionQueue.length) {
    alertToast('本關設定的題目已全部完成');
    return;
  }
  closeModal();
  showQuiz();
}

function showQuiz() {
  if (!stage || ended || quizOpen || questionsAnswered >= questionQueue.length) return;
  activeQuestion = questionQueue[questionsAnswered];
  if (!activeQuestion) return;
  quizOpen = true;
  quizLock = false;

  let q = activeQuestion;
  let opts = shuffle(q.options.map((txt, i) => ({ txt, i })));
  modal(`
    <h2>📖 生物知識挑戰 ${questionsAnswered + 1}／${questionQueue.length}</h2>
    <p>${esc(q.question)}</p>
    <div class="quizChoices">
      ${opts.map(x => `<button type="button" class="choice" onclick="answerQuiz(${x.i})">${esc(x.txt)}</button>`).join('')}
    </div>
    <div id="quizFeedback" class="quizFeedback">答題期間，關卡倒數完全暫停。</div>
  `);
  say('小雞出題！動動腦筋，選出正確解答吧！');
}

function answerQuiz(i) {
  if (!quizOpen || quizLock || !activeQuestion) return;
  let q = activeQuestion;
  if (i !== q.answer) {
    tone(250);
    const fb = $('quizFeedback');
    if (fb) fb.textContent = '再想一想！答錯不扣題數，可以換個選項重試。';
    return;
  }

  quizLock = true;
  askedIds.add(q.id);
  questionsAnswered++;
  tone(950, .2);

  modal(`
    <h2>🎉 答對了！</h2>
    <p>${esc(q.explanation || '生物知識任務完成！')}</p>
    <button type="button" class="btn" onclick="finishQuiz()">繼續完成分類任務</button>
  `);
  say('答對了！太厲害了，繼續拯救羊羊！');
}

function finishQuiz() {
  quizOpen = false;
  quizLock = false;
  activeQuestion = null;
  closeModal();
  if (maybeAskQuiz()) return;
  checkCompletion();
}

function checkCompletion() {
  if (!stage || ended || board.some(p => p.some(c => !c.decoy)) || tray.length) return;
  if (taskIndex !== stageTasks.length) {
    modal('<h2>還有分類任務未完成</h2><button type="button" class="btn" onclick="closeModal()">繼續</button>');
    return;
  }
  if (questionsAnswered < questionQueue.length) {
    showQuiz();
    return;
  }
  finishWin();
}

function timeChallengeFailed() {
  if (!challengeEndAt || ended || quizOpen) return;
  challengeEndAt = 0;
  challengeFailed.add(taskIndex);
  say('野狼追上來了！別灰心，再試一次！');
  tone(220, .3);
  modal(`
    <h2>🐺 野狼追擊！</h2>
    <p>這次限時選牌沒有及時完成，不會扣分，也不會清除已選圖卡。</p>
    <p>再給你 ${settings.challengeSeconds} 秒，繼續找出三張相同且符合條件的圖卡！</p>
    <button type="button" class="btn" onclick="closeModal();startChallengeIfNeeded();render()">再挑戰一次</button>
  `);
}

function updateClocks() {
  if (!stage || ended) return;
  let c = $('mainClock');
  if (c) {
    c.textContent = mmss(remainingMs());
    c.classList.toggle('urgent', remainingMs() < 30000 && !settings.noTime);
  }
  let t = $('challengeClock');
  if (t) {
    t.textContent = challengeEndAt ? Math.max(0, Math.ceil((challengeEndAt - (clockPauseAt || Date.now())) / 1000)) : settings.challengeSeconds;
  }
}

setInterval(() => {
  if (!stage || ended || clockPauseAt) return;
  updateClocks();
  if (!settings.noTime && remainingMs() <= 0) {
    ended = true;
    challengeEndAt = 0;
    quizOpen = false;
    modal(`
      <h2>⏰ 本次挑戰時間到</h2>
      <p>已取得 ${cleared.size} 枚關卡認證：${[...cleared].sort().map(n => LEVELS[n].award).join('、') || '今天的農場探索也很有收穫！'}</p>
      <p>每完成一關，都是值得肯定的生物知識成就。</p>
      ${settings.timeMode === 'stage' ? '<button type="button" class="btn" onclick="startLevel(stage)">🔄 重試本關</button>' : ''}
      <button type="button" class="btn dark" onclick="showHome()">返回首頁</button>
    `);
    return;
  }
  if (challengeEndAt && Date.now() >= challengeEndAt) timeChallengeFailed();
}, 150);

function undo() {
  if (usedUndo >= 1) {
    alertToast('撤回次數已用完');
    return;
  }
  let old = history.pop();
  if (!old) {
    alertToast('還沒有可撤回的動作');
    return;
  }
  board = old.board;
  tray = old.tray;
  taskIndex = old.taskIndex;
  taskGroupsDone = old.taskGroupsDone;
  matched = old.matched;
  challengeEndAt = old.challengeEndAt;
  stageTasks = old.stageTasks;
  usedUndo++;
  render();
}

function rescue() {
  if (rescueAsked >= settings.rescueLimits[stage]) {
    alertToast('救援退回次數已用完');
    return;
  }
  if (!tray.length) {
    alertToast('暫存槽目前沒有圖卡');
    return;
  }
  snapshot();
  let returned = tray.splice(0, Math.min(3, tray.length));
  returned.forEach((icon, k) => {
    let p = Number.isInteger(icon.sourceIndex) ? icon.sourceIndex : board.findIndex(a => a.length < LEVELS[stage].depth);
    board[p >= 0 ? p : (k * 7) % board.length].push(icon);
  });
  rescueAsked++;
  render();
  say('暫存槽有空位了！繼續加油！');
}

function teacherWin() {
  if (studentMode || !stage) return;
  board = Array.from({ length: board.length }, () => []);
  tray = [];
  taskIndex = stageTasks.length;
  questionsAnswered = questionQueue.length;
  quizOpen = false;
  ended = false;
  finishWin();
}

function finishWin() {
  if (!stage || ended) return;
  ended = true;
  challengeEndAt = 0;
  cleared.add(stage);
  safeSave();

  say('恭喜過關！咕咕咕！羊羊安全逃脫了！');
  tone(960, .28);

  let lev = LEVELS[stage];
  let next = stage < 3
    ? (!settings.noTime && settings.timeMode === 'total' && remainingMs() <= 0
        ? `<button type="button" class="btn" onclick="showHome()">🏡 返回首頁</button>`
        : `<button type="button" class="btn" onclick="startLevel(${stage + 1})">➡️ 挑戰下一關</button>`)
    : `<button type="button" class="btn" onclick="showHome()">🎉 返回首頁</button>`;

  window.lastCert = `
    <div class="cert">
      <div style="font-size:56px">🏅</div>
      <h3>羊羊英雄認證</h3>
      <h2>${lev.award}</h2>
      <p>恭喜成功通過<br>第 ${stage} 關｜${lev.title}</p>
      <small>羊羊農場：生物大逃脫</small>
    </div>
  `;

  modal(`
    ${window.lastCert}
    <div style="margin-top:12px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
      <button type="button" class="btn alt" onclick="printCert()">🖨️ 列印／儲存獎狀</button>
      ${next}
      <button type="button" class="btn dark" onclick="closeModal()">留在本關</button>
    </div>
  `);
}

function printCert() {
  const prt = $('printCertificate');
  if (prt) prt.innerHTML = window.lastCert || '';
  window.print();
}

// 🐥 伴讀小雞拖曳與表情切換模組
const SPRITES = {"normal":"data:image/webp;base64,","happy":"data:image/webp;base64,","jump":"data:image/webp;base64,","thinking":"data:image/webp;base64,","dizzy":"data:image/webp;base64,","worried":"data:image/webp;base64,"};

function initDraggableChick() {
  const chick = $('chick');
  const bubble = $('speech');
  const sprite = $('chickSprite');
  if (!chick || !bubble || !sprite) return;

  let current = 'normal';
  let restTimer = null;

  // 預載表情
  Object.values(SPRITES).forEach(src => {
    let img = new Image();
    img.src = src;
  });

  function setMood(mood, hold = 0) {
    const moodName = SPRITES[mood] ? mood : 'normal';
    clearTimeout(restTimer);
    const change = moodName !== current;
    current = moodName;

    chick.classList.remove('excited', 'worried', 'thinking');
    if (moodName === 'happy' || moodName === 'jump') chick.classList.add('excited');
    else if (moodName === 'worried' || moodName === 'dizzy') chick.classList.add('worried');
    else if (moodName === 'thinking') chick.classList.add('thinking');

    if (change) {
      sprite.src = SPRITES[moodName];
      sprite.alt = '小雞表情：' + ({ 'normal': '微笑', 'happy': '歡呼', 'jump': '跳躍', 'thinking': '思考', 'worried': '緊張', 'dizzy': '頭暈' }[moodName] || '微笑');
    }

    if (hold) restTimer = setTimeout(() => setMood('normal'), hold);
  }

  function react() {
    const t = bubble.textContent || '';
    if (/恭喜|過關|成功|太棒|完成|獲得|勝利|答對|棒|歡呼/.test(t)) setMood('happy', 4600);
    else if (/暈|搞混|糊塗/.test(t)) setMood('dizzy', 4200);
    else if (/危險|快滿|失敗|野狼|不好|糟糕|滿了|答錯|救命|追/.test(t)) setMood('worried', 4300);
    else if (/想想|問題|準備|思考|生物|答題|加油/.test(t)) setMood('thinking', 3600);
    else setMood('normal');
  }

  new MutationObserver(react).observe(bubble, { subtree: true, childList: true, characterData: true });
  window.sheepChickMood = setMood;

  // 點擊對話氣泡可收合或展開
  bubble.addEventListener('click', () => {
    bubble.classList.toggle('collapsed');
  });

  // 觸控與滑鼠拖曳小雞
  let isDragging = false;
  let startX = 0, startY = 0;
  let startLeft = 0, startTop = 0;

  chick.addEventListener('pointerdown', e => {
    if (e.target === bubble || bubble.contains(e.target)) return;
    if (e.button && e.button !== 0) return;

    isDragging = true;
    chick.classList.add('is-dragging');
    try { chick.setPointerCapture(e.pointerId); } catch (_) {}

    const rect = chick.getBoundingClientRect();
    startX = e.clientX;
    startY = e.clientY;
    startLeft = rect.left;
    startTop = rect.top;

    chick.style.position = 'fixed';
    chick.style.bottom = 'auto';
    chick.style.right = 'auto';
    chick.style.left = `${startLeft}px`;
    chick.style.top = `${startTop}px`;
    e.preventDefault();
  });

  chick.addEventListener('pointermove', e => {
    if (!isDragging) return;
    const dx = e.clientX - startX;
    const dy = e.clientY - startY;

    const maxLeft = Math.max(10, window.innerWidth - chick.offsetWidth - 10);
    const maxTop = Math.max(10, window.innerHeight - chick.offsetHeight - 10);

    const nextLeft = Math.min(Math.max(10, startLeft + dx), maxLeft);
    const nextTop = Math.min(Math.max(10, startTop + dy), maxTop);

    chick.style.left = `${nextLeft}px`;
    chick.style.top = `${nextTop}px`;
  });

  const stopDrag = e => {
    if (!isDragging) return;
    isDragging = false;
    chick.classList.remove('is-dragging');
    try { chick.releasePointerCapture(e.pointerId); } catch (_) {}
  };

  chick.addEventListener('pointerup', stopDrag);
  chick.addEventListener('pointercancel', stopDrag);
}

// 展開教師設定浮鈕綁定
window.addEventListener('DOMContentLoaded', () => {
  const expandBtn = $('expandHomeBtn');
  if (expandBtn) expandBtn.onclick = expandTeacherHome;
  initDraggableChick();
});

// 適配器回呼 Hook
window.__ESCAPE_HOOK__ = {
  type: "farm",
  setBank: (b) => {
    if (Array.isArray(b) && b.length) {
      questionBank = b;
      activeQuestionUnit = 'adapter';
    }
  }
};

// 啟動首頁
showHome();
